/**
 * dsh-openai-account-ui — client half（浏览器 bundle）
 *
 * 在 dsh 设置页新增「OpenAI 账号」分节，把 OpenAI 账号登录/登出/状态
 * 集成到 Web UI，而不是依赖用户在聊天框里敲 `/openai-login`。
 *
 * 实现方式：不新增任何 host RPC。设置页按钮通过客户端已有的
 * `ctx.remote.commands.execute(sessionId, line, [])`
 * 调用 `openai-codex-account` 插件注册的斜杠命令；登录过程中的交互对话框
 * （选择登录方式、设备码、浏览器授权码）由 dsh 的 userQuestions UI 呈现。
 */

;(function registerClientBundle() {
  if (typeof window === 'undefined' || typeof window.__ModuleLoader__ === 'undefined') return
  window.__ModuleLoader__.load({
    id: 'dsh-openai-account-ui',
    factory: function openaiAccountUIFactory(require) {
      'use strict'
      const React = require('react')
      const { Button } = require('@deepseek-ai/dsh-client-ui-primitives')

      // ── 文案 ──────────────────────────────────────────────────────
      const NS = 'openai-account'
      const zh = {
        nav: 'OpenAI 账号',
        heading: 'OpenAI 账号（ChatGPT Plus/Pro）',
        description: '使用 OpenAI 账号（token plan）调用 openai-codex 模型，无需 API key。',
        noSession: '请先打开一个会话，再管理 OpenAI 账号。',
        status: '状态',
        notLoggedIn: '未登录',
        loggedIn: '已登录',
        login: '登录',
        loginHint: '浏览器或设备码登录 OpenAI 账号',
        logout: '登出',
        logoutHint: '清除已保存的 OpenAI 账号凭据',
        refreshing: '刷新中…',
        working: '处理中…',
        error: '出错了',
        unknown: '未知',
        accountId: '账号',
        expires: '有效期',
      }
      const en = {
        nav: 'OpenAI Account',
        heading: 'OpenAI Account (ChatGPT Plus/Pro)',
        description: 'Use your OpenAI account token plan to call openai-codex models, no API key needed.',
        noSession: 'Open a conversation first, then manage your OpenAI account.',
        status: 'Status',
        notLoggedIn: 'Not logged in',
        loggedIn: 'Logged in',
        login: 'Sign in',
        loginHint: 'Sign in to OpenAI with browser or device code',
        logout: 'Sign out',
        logoutHint: 'Clear saved OpenAI account credentials',
        refreshing: 'Refreshing…',
        working: 'Working…',
        error: 'Error',
        unknown: 'Unknown',
        accountId: 'Account',
        expires: 'Expires',
      }

      // ── 解析命令结果文本 ──────────────────────────────────────────
      function resultText(result) {
        if (result?.ok === true) {
          const command = result.value
          if (command && command.result) {
            if (command.result.kind === 'success') return command.result.text ?? 'OK'
            return command.result.text ?? 'ERROR'
          }
          return 'OK'
        }
        const err = result?.error
        if (err) return err.message || err.code || 'UNKNOWN'
        return 'UNKNOWN'
      }

      function SectionCard({ title, children }) {
        return React.createElement('section', { className: 'oau-card' },
          React.createElement('h3', { className: 'oau-title' }, title),
          children)
      }

      function Field({ label, value }) {
        return React.createElement('div', { className: 'oau-field' },
          React.createElement('span', { className: 'oau-fieldLabel' }, label),
          React.createElement('span', { className: 'oau-fieldValue' }, value))
      }

      /**
       * 设置页分节组件。通过 useSyncExternalStore 订阅当前会话 id，
       * 然后调用 commands/execute 读取状态或触发登录/登出。
       */
      function OpenAIAccountSection(props) {
        const { t } = props
        const ctx = props.__ctx // apply 闭包注入
        const [status, setStatus] = React.useState(null) // { loggedIn, text, raw }
        const [busy, setBusy] = React.useState(false)
        const [error, setError] = React.useState(null)

        const sessionId = React.useSyncExternalStore(
          React.useCallback(
            (onChange) => ctx.sessions.list.subscribe(onChange),
            [ctx],
          ),
          () => ctx.sessions.list.getSnapshot().current,
          () => ctx.sessions.list.getSnapshot().current,
        )

        const refresh = React.useCallback(async () => {
          if (!sessionId) {
            setStatus(null)
            setError(null)
            return
          }
          setBusy(true)
          setError(null)
          try {
            const result = await ctx.remote.commands.execute(sessionId, '/openai-status', [])
            const text = resultText(result)
            // 识别状态文本中的关键信息
            setStatus({
              loggedIn: text.includes('已登录') || text.includes('Logged in'),
              text,
            })
          } catch (err) {
            setError(err?.message ?? String(err))
            setStatus(null)
          } finally {
            setBusy(false)
          }
        }, [sessionId, ctx])

        React.useEffect(() => {
          void refresh()
        }, [refresh])

        const run = React.useCallback(async (line) => {
          if (!sessionId) return
          setBusy(true)
          setError(null)
          try {
            const result = await ctx.remote.commands.execute(sessionId, line, [])
            const text = resultText(result)
            // 登录/登出完成后刷新状态
            setStatus({
              loggedIn: text.includes('已登录') || text.includes('Logged in'),
              text,
            })
          } catch (err) {
            setError(err?.message ?? String(err))
          } finally {
            setBusy(false)
          }
        }, [sessionId, ctx])

        const login = React.useCallback(() => void run('/openai-login'), [run])
        const logout = React.useCallback(() => void run('/openai-logout'), [run])

        if (!sessionId) {
          return React.createElement('section', { className: 'oau-root' },
            React.createElement('p', { className: 'oau-muted' }, t('noSession')))
        }

        return React.createElement('section', { className: 'oau-root' },
          React.createElement('h2', { className: 'oau-heading' }, t('heading')),
          React.createElement('p', { className: 'oau-muted' }, t('description')),

          React.createElement(SectionCard, { title: t('status') },
            error !== null
              ? React.createElement(Field, { label: t('error'), value: error })
              : status === null
                ? React.createElement('p', { className: 'oau-muted' }, busy ? t('refreshing') : t('notLoggedIn'))
                : React.createElement('div', { className: 'oau-status' },
                    React.createElement('span', {
                      className: status.loggedIn ? 'oau-dot oau-dot-on' : 'oau-dot oau-dot-off',
                    }),
                    React.createElement('pre', { className: 'oau-text' }, status.text))),

          React.createElement('div', { className: 'oau-actions' },
            React.createElement(Button, {
              variant: 'primary',
              disabled: busy,
              title: t('loginHint'),
              onClick: login,
            }, t('login')),
            React.createElement(Button, {
              variant: 'outline',
              disabled: busy,
              title: t('logoutHint'),
              onClick: logout,
            }, t('logout'))),
        )
      }

      // CSS 注入
      const cssText = `
.oau-root { display: flex; flex-direction: column; gap: 16px; max-width: 640px; }
.oau-heading { margin: 0; font-size: 18px; font-weight: 600; color: var(--dsw-alias-label-primary); }
.oau-muted { margin: 0; color: var(--dsw-alias-label-secondary); font-size: 13px; line-height: 20px; }
.oau-card { border: 1px solid var(--dsw-alias-border-l2); border-radius: 12px; background: var(--dsw-alias-bg-base); padding: 14px 16px; }
.oau-title { margin: 0 0 10px; font-size: 13px; font-weight: 600; color: var(--dsw-alias-label-primary); }
.oau-field { display: flex; gap: 12px; align-items: baseline; padding: 4px 0; }
.oau-fieldLabel { color: var(--dsw-alias-label-secondary); font-size: 12px; min-width: 72px; }
.oau-fieldValue { color: var(--dsw-alias-label-primary); font-size: 13px; word-break: break-all; }
.oau-status { display: flex; gap: 8px; align-items: flex-start; }
.oau-dot { width: 8px; height: 8px; border-radius: 50%; margin-top: 5px; flex: none; }
.oau-dot-on { background: var(--dsw-alias-state-success-primary); }
.oau-dot-off { background: var(--dsw-alias-state-warn-primary); }
.oau-text { margin: 0; white-space: pre-wrap; word-break: break-word; color: var(--dsw-alias-label-primary); font-size: 13px; line-height: 20px; font-family: var(--ds-font-family-code, monospace); }
.oau-actions { display: flex; gap: 8px; }
`
      if (typeof document !== 'undefined') {
        const style = document.createElement('style')
        style.textContent = cssText
        document.head.appendChild(style)
      }

      /** 客户端插件导出：注册设置页分节。 */
      return {
        name: 'dsh-openai-account-ui',
        // 访问 ctx.remote.commands 必须显式注入 remote.commands 命名空间服务
        inject: ['slots', 'locale', 'remote', 'remote.commands', 'sessions'],
        apply(ctx) {
          const t = ctx.locale.bind(NS)
          ctx.effect(() => ctx.locale.register(NS, { zh, en }), 'dsh-openai-account-ui: dictionaries')

          // 把 ctx 通过 props 透传给组件（组件在 apply 闭包外定义，拿不到 ctx）。
          const withCtx = (Component) => (props) => React.createElement(Component, { ...props, __ctx: ctx })

          ctx.slots.inject('settings.section', () => ctx.slots.register({
            name: 'settings.section',
            id: 'openai-account',
            order: 15,
            label: () => t('nav'),
            locale: NS,
          }, withCtx(OpenAIAccountSection)))
        },
      }
    },
  })
})()
